function o(n,a,s,t={}){if(!n)return{isValid:!1,message:"Please select a status"};const l=String(n||"").trim().toLowerCase(),i=Array.isArray(a)?a.find(e=>String(e?.status||"").trim().toLowerCase()===l):null;if(i){if(i.requirePayment100Percent===!0){const e=Number(t.total)||Number(s?.totalAmount)||0,r=Number(t.paid)||Number(s?.paidAmount)||0;if(e===0)return{isValid:!1,message:`Please set the total amount before changing status to ${n}`};if(r<e)return{isValid:!1,message:`Payment pending. Please complete 100% payment before changing status to ${n}. (Paid: $${r}, Total: $${e})`}}if(i.requireDesignUpload===!0&&!(s?.designStartAt||s?.designEndAt||s?.designFinalFileName||s?.designFinalFilePath))return{isValid:!1,message:`Please complete design before changing status to ${n}`};if(Array.isArray(i.requireFields)){for(const e of i.requireFields)if(!s?.[e])return{isValid:!1,message:`Please fill in ${e} before changing status to ${n}`}}if(i.validationMessage&&i.validationCheck===!1)return{isValid:!1,message:i.validationMessage}}return{isValid:!0,message:""}}export{o as v};
